// Intl step I4: PluralRules, ListFormat, RelativeTimeFormat. Every exported function without
// parameters returns a string; `gen_intl4_expected.ts` runs this file in bun. Generated by
// bench/gen_intl4_program.py (the option sets are written out because Platypus reads them as literals).

function fail(f: () => string): string {
  try {
    return f();
  } catch (e) {
    return (e as Error).name + ": " + (e as Error).message;
  }
}

const NUMS = [0, 1, 2, 3, 4, 5, 6, 7, 10, 11, 12, 13, 14, 20, 21, 22, 25, 100, 101, 102, 111, 1000, 1000000, 0.5, 1.5, 2.5, -1, -2];

