export function pluralFraction(): string {
  const a = new Intl.PluralRules("en", { minimumFractionDigits: 1 });
  const b = new Intl.PluralRules("en", { maximumFractionDigits: 0 });
  const c = new Intl.PluralRules("fr", { minimumFractionDigits: 2 });
  return [1, 1.0, 2, 1.5, 0.99, 1.4].map((n) => a.select(n) + "/" + b.select(n) + "/" + c.select(n)).join(",") + "|" + new Intl.PluralRules("en").select(NaN) + new Intl.PluralRules("en").select(Infinity);
}

export function pluralErrors(): string {
  return [
    fail(() => new Intl.PluralRules("en", { type: "x" as any }).select(1)),
    fail(() => new Intl.PluralRules("bad tag!").select(1)),
  ].join("\n");
}

