export function listDefaults(): string {
  return [new Intl.ListFormat("en").format(["a", "b", "c"]), new Intl.ListFormat("de").format(["x", "y"]), new Intl.ListFormat("en", { style: "short" }).format(["p", "q", "r"])].join("|");
}

export function listErrors(): string {
  return [
    fail(() => new Intl.ListFormat("en", { style: "x" as any }).format(["a"])),
    fail(() => new Intl.ListFormat("en", { type: "x" as any }).format(["a"])),
    fail(() => new Intl.ListFormat("bad tag!").format(["a"])),
  ].join("\n");
}

