    out += [f.format(-3, "month"), f.format(-1, "month"), f.format(0, "month"), f.format(1, "month"), f.format(2, "month"), f.format(5, "month"), f.format(1.5, "month"), f.format(-0.5, "month"), f.format(100, "month")].join(" | ") + " ; ";
    out += [f.format(-3, "quarter"), f.format(-1, "quarter"), f.format(0, "quarter"), f.format(1, "quarter"), f.format(2, "quarter"), f.format(5, "quarter"), f.format(1.5, "quarter"), f.format(-0.5, "quarter"), f.format(100, "quarter")].join(" | ") + " ; ";
